Read the month headers and apple counts from the data sheet and compute the cumulative counts. For each apple index in A9:A100, find the first cumulative count that is at least the index, which implements the “add 1 if not present” rule. Write the corresponding month numbers as plain values into the active sheet’s B9:B100.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

answer_sheet = wb.active.title
ws = wb[answer_sheet]

def sheet_has_table(w):
    if w.max_column < 3:
        return False
    return any(
        w.cell(row=r, column=c).value is not None
        for r in (4, 5, 6)
        for c in range(3, w.max_column + 1)
    )

def sheet_has_index(w):
    return any(w.cell(row=r, column=1).value is not None for r in range(9, 101))

data_sheet = None
for name in (answer_sheet, "Sheet1"):
    if name in vals.sheetnames and sheet_has_table(vals[name]):
        data_sheet = name
        break

if data_sheet is None:
    for name in (answer_sheet, "Sheet1"):
        if name in vals.sheetnames and sheet_has_index(vals[name]):
            data_sheet = name
            break

if data_sheet is None:
    data_sheet = answer_sheet if answer_sheet in vals.sheetnames else vals.active.title

vws = vals[data_sheet]

def to_num(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        return x
    try:
        return float(x)
    except Exception:
        return None

def clean_out(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, float) and x.is_integer():
        return int(x)
    if isinstance(x, str):
        s = x.strip()
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except Exception:
            return s
    return x

# Determine the last data column in the horizontal table.
last_col = 2
for c in range(3, vws.max_column + 1):
    if any(vws.cell(row=r, column=c).value is not None for r in (4, 5, 6)):
        last_col = c
if last_col < 3:
    last_col = 22

months = [to_num(vws.cell(row=4, column=c).value) for c in range(3, last_col + 1)]
sold = [to_num(vws.cell(row=5, column=c).value) for c in range(3, last_col + 1)]
accum_raw = [to_num(vws.cell(row=6, column=c).value) for c in range(3, last_col + 1)]

# Prefer recomputing the cumulative row from apples sold; fall back to cached accum row.
if any(s is not None for s in sold):
    accum = []
    total = 0
    for s in sold:
        total += s if s is not None else 0
        accum.append(total)
else:
    accum = accum_raw

# If month headers are missing, infer sequential month numbers.
if any(m is None for m in months):
    known = [(i, m) for i, m in enumerate(months) if m is not None]
    if not known:
        months = [float(i + 1) for i in range(len(months))]
    else:
        first_i, first_m = known[0]
        for i in range(first_i):
            months[i] = float(i + 1)
        last = first_m
        for i in range(first_i, len(months)):
            if months[i] is None:
                last += 1
                months[i] = last
            else:
                last = months[i]

def month_for_index(idx):
    if idx is None:
        return None

    # First cumulative month whose accumulated apples is >= the apple index.
    for i, a in enumerate(accum):
        if a is not None and a >= idx:
            if i < len(months) and months[i] is not None:
                return months[i]
            return float(i + 1)

    # Fallback for an index beyond the total: use the last month.
    if accum and months:
        return months[-1] if months[-1] is not None else float(len(accum))
    return None

filled = 0
for r in range(9, 101):
    idx = to_num(vws.cell(row=r, column=1).value)
    if idx is None:
        # Sample structure has A9:A100 = 1:92; use this only as a fallback.
        idx = float(r - 8)

    m = month_for_index(idx)
    ws.cell(row=r, column=2).value = clean_out(m)
    filled += 1

    if r <= 15:
        print(r, idx, ws.cell(row=r, column=2).value)

print("filled", filled, "rows; total apples =", accum[-1] if accum else None)
wb.save(OUT)
